{"code": "import re, os, glob, json

root = '/online1/ycsc_chenkh/hitici_07/deepseek-harness/attached_files/task_9'
files = [f for f in sorted(glob.glob(root + '/**/*', recursive=True)) if os.path.isfile(f) and not f.endswith('.xlsx')]

out = {}
for f in files:
    txt = open(f, encoding='utf-8', errors='replace').read()
    b = os.path.basename(f)
    num = int(re.search(r'(\d+)', b).group(1))
    # role
    role = ''
    m = re.search(r'[Ee]vidence role:?\s*<?dt>?([a-z_]+)', txt)
    if not m: m = re.search(r'evidence_role,([a-z_]+)', txt)
    if not m: m = re.search(r'"evidence_role":\s*"([a-z_]+)"', txt)
    if not m: m = re.search(r'evidence-role>([a-z_]+)<', txt)
    if not m: m = re.search(r'Evidence role\</dt\>\<dd\>([a-z_]+)', txt)
    if not m: m = re.search(r'evidence_role is ([a-z_]+)', txt)
    if m: role = m.group(1)
    if not role:
        if 'supplies correspondence evidence' in txt: role='correspondence'
        elif 'supplies identity crosswalk evidence' in txt: role='identity_crosswalk'
        elif 'supplies operative authority evidence' in txt: role='operative_authority'
        elif 'supplies approval and capacity evidence' in txt: role='approval_and_capacity'
        elif 'supplies current operations evidence' in txt: role='current_operations'
        elif 'supplies financial or population support evidence' in txt: role='financial_or_population_support'
        elif 'independent counterrecord' in txt.lower(): role='independent_counterrecord'
    # native record statement
    nat = ''
    m = re.search(r'(?:NATIVE RECORD|Native record|<native-record>|"text":\s*"[^"]*(?:must come|blocks|threshold|due by|limited to|result|names|roster|asks|repeats|completed|occurred|score)[^"]*")\s*(.*?)(?:RELIANCE|Reliance|</native-record>|SOURCE LINEAGE|Source lineage)', txt, re.S)
    if m:
        nat = re.sub(r'<[^>]+>', ' ', m.group(1))
        nat = re.sub(r'\s+', ' ', nat).strip()
    if not nat and 'body,' in txt:
        m = re.search(r'body,"([^"]+)"', txt)
        if m: nat = m.group(1)
    if not nat:
        m = re.search(r'"body":\s*"([^"]+)"', txt, re.S)
        if m: nat = m.group(1)
    if not nat:
        m = re.search(r'<native-record>(.*?)</native-record>', txt, re.S)
        if m: nat = re.sub(r'\s+',' ', m.group(1)).strip()
    if not nat:
        # eml: text after headers, before SOURCE LINEAGE
        m = re.search(r'Content-Type:[^\n]*\n\n(.*?)\n\nSOURCE LINEAGE', txt, re.S)
        if m: nat = re.sub(r'\s+',' ', m.group(1)).strip()
    # fallback: any sentence with CB-MA-2401-R or E ref and key verb, not support row
    if not nat:
        cands = [re.sub(r'\s+',' ',s).strip() for s in re.findall(r'[^.\n]*(?:must come from|blocks completion|is limited to|threshold is|approval names|is due by|activity occurred|event completed|result is|roster names|asks whether|points to|repeats|score)[^.\n]*\.', txt) if 'support row' not in s.lower()]
        nat = cands[0] if cands else ''
    out[num] = {'file': b, 'role': role, 'nat': nat[:500]}

for num in sorted(out):
    v = out[num]
    if v['nat'] or v['role']:
        print(f"[{num:03d}] {v['file'].split('_')[1]:<18} role={v['role']:<32} :: {v['nat'][:330]}")
"}

