    if m: nat = m.group(1)
    if not nat:
        m = re.search(r'<native-record>(.*?)</native-record>', txt, re.S)
        if m: nat = m.group(1)
    if not nat:
        m = re.search(r'body,"([^"]+)"', txt)
        if m: nat = m.group(1)
    if not nat:
        m = re.search(r'(?:NATIVE RECORD|Native record)\s*(.*?)(?:RELIANCE|Reliance)', txt, re.S)
        if m: nat = re.sub(r'\s+',' ', m.group(1)).strip()
    if not nat:
        m = re.search(r'Content-Type:[^\n]*\n\n(.*?)\n\nSOURCE LINEAGE', txt, re.S)
        if m: nat = re.sub(r'\s+',' ',m.group(1)).strip()
    role = ''
    for pat in [r'[Ee]vidence role:?\s*([a-z_]+)', r'"evidence_role":\s*"([a-z_]+)"', r'evidence_role,([a-z_]+)', r'evidence-role>([a-z_]+)<']:
        m = re.search(pat, txt)
        if m: role = m.group(1); break
    print(f"[{num}] {os.path.basename(f)} role={role}")
    print("   ", re.sub(r'\s+',' ', nat)[:400])
